function preferredLanguage(){try{return localStorage.getItem('udyam_language')==='hi'?'hi':'en';}catch{return 'en';}}
function advisorErrorText(reason){
  const invalid=['AI_INVALID_REPLY','AI_QUOTE_MISMATCH','AI_INCOMPLETE'].includes(reason)||String(reason||'').includes('json_validate_failed');
  const english={AI_RATE_LIMIT:'Our AI advisor is receiving many requests. Please try again shortly.',AI_NETWORK_ERROR:'Connection problem. Please check your internet connection.',AI_TIMEOUT:'The advisor took too long to respond. Please try again.'}[reason]||(invalid?'We couldn’t process that response. Please try again.':'The advisor is temporarily unavailable. Please try again.');
  const hindi={AI_RATE_LIMIT:'हमारे AI सलाहकार को अभी बहुत अनुरोध मिल रहे हैं। कृपया थोड़ी देर बाद कोशिश करें।',AI_NETWORK_ERROR:'कनेक्शन में समस्या है। कृपया इंटरनेट जाँचें।',AI_TIMEOUT:'सलाहकार को जवाब देने में ज़्यादा समय लगा। कृपया फिर से कोशिश करें।'}[reason]||(invalid?'हम इस जवाब को समझ नहीं पाए। कृपया फिर से कोशिश करें।':'सलाहकार अभी उपलब्ध नहीं है। कृपया फिर से कोशिश करें।');
  return tr(english,hindi);
}
const state = { customerSignedIn:false, step:0, reached:0, advisorOpen:false, advisorSize:null, historyOpen:false, gstConsent:false, registrationCheck:null, conversationStorage:'disabled', conversations:[], activeConversation:null, requirementsRevision:0, pendingForm:null, formConfirmed:false, advisorProfile:null, chatHasMore:false, pendingChat:null, advisorDraft:'', mode:'guided', provider:'groq', externalImageReading:false, busy:false, error:'', extractionMethod:'local', eligible:[], quote:null, warnings:[], profile:{businessName:'',segment:'prof',employees:5,sites:1,cityTier:1,budget:3000,needs:['internet','email'],currentTools:'',language:preferredLanguage(),gstin:'',udyam:''}, contact:{name:'',phone:'',address:''}, consent:false, aiConsent:false, documents:{}, kycCaseId:null, kycStorage:'temporary', verification:null, fieldsReviewed:false, order:null, correctionOrderId:null, orders:[], notifications:[], notificationsOpen:false, messages:[], proposed:null, advisorOffers:[], requestKey:crypto.randomUUID() };
