const reviewFieldNames = {gstinReadUncertain:'GSTIN reading needs review',gstinReadAdjustment:'OCR reading adjustment',tradeName:'Trade name',registrationStatus:'Certificate registration status',enterpriseClassification:'Enterprise classification',registrationDate:'Registration date',majorActivity:'Major activity',businessName:'Business name',gstin:'GSTIN (masked)',udyam:'Udyam number (masked)',address:'Address',documentDate:'Document date',signatoryName:'Signatory name',validTill:'ID valid until'};
async function api(path, input, method) {
  const authToken=await customerToken();
  let response;
  try { response = await fetch('/api'+path,{method:method || (input?'POST':'GET'),credentials:'same-origin',headers:{...(input || method==='DELETE'?{'Content-Type':'application/json'}:{}),...(authToken?{Authorization:'Bearer '+authToken}:{})},body:input?JSON.stringify(input):undefined}); }
  catch(error){if(path.endsWith('/chat')||path==='/advisor')throw new Error(advisorErrorText('AI_NETWORK_ERROR'));throw error;}
  const data = await response.json(); if(!response.ok){const error=new Error(data.error || 'Request failed.');error.code=data.code;throw error;} return data;
}
function invalidate(){state.verification=null;state.fieldsReviewed=false;state.requestKey=crypto.randomUUID();}
