let notificationPolling=false,notificationsLoaded=false,notificationTimer;
function renderNotifications(){
 const unread=state.notifications.filter(item=>!item.read),count=$('#notification-count'),toggle=$('#notification-toggle');
 count.hidden=!unread.length;count.textContent=unread.length>99?'99+':String(unread.length);toggle.setAttribute('aria-label',unread.length?`Notifications, ${unread.length} unread`:'Notifications, no unread messages');
 $('#mark-notifications-read').hidden=!unread.length;$('#notification-summary').textContent=unread.length?`${unread.length} unread message${unread.length===1?'':'s'}`:'Messages from sales and KYC review';
 $('#notification-list').innerHTML=state.notifications.length?state.notifications.map(item=>`<a class="notification-item ${item.read?'':'unread'}" data-notification-link data-notification-id="${esc(item.id)}" href="/?view=checkout&order_id=${encodeURIComponent(item.orderId)}"><span class="notification-item-heading"><b>${esc(item.title)}</b>${item.read?'':'<i>New</i>'}</span><span class="notification-message" data-user-content>${esc(item.message)}</span><small>${esc(new Date(item.createdAt).toLocaleString('en-IN',{timeZone:'Asia/Kolkata'}))} · View order</small></a>`).join(''):'<p class="notification-empty">No sales or KYC messages yet.</p>';
}
async function refreshNotifications(){
 if(!state.customerSignedIn||document.hidden||notificationPolling)return;notificationPolling=true;
 try{const previous=new Set(state.notifications.map(item=>item.id)),data=await api('/notifications');state.notifications=data.notifications||[];if(notificationsLoaded){const incoming=state.notifications.filter(item=>!item.read&&!previous.has(item.id));if(incoming.length)notify(incoming[0].type==='reviewer_message'?'New message from your KYC reviewer.':'New reply from sales.');}notificationsLoaded=true;renderNotifications();}
 catch{if(!state.notifications.length)$('#notification-list').innerHTML='<p class="notification-empty">Notifications are temporarily unavailable. Please try again shortly.</p>';}
 finally{notificationPolling=false;}
}
function startNotifications(){$('#notification-center').hidden=false;renderNotifications();refreshNotifications();clearInterval(notificationTimer);notificationTimer=setInterval(refreshNotifications,10000);}
async function markNotificationsRead(ids){if(!ids.length)return;await api('/notifications/read',{ids});const read=new Set(ids);state.notifications=state.notifications.map(item=>read.has(item.id)?{...item,read:true}:item);renderNotifications();}
async function run(action,message){if(state.busy)return;state.busy=true;state.error='';$('#activity').hidden=false;$('#activity').textContent=message||tr('Working on it…','काम हो रहा है…');$('#view').setAttribute('aria-busy','true');if($('#advisor-widget'))renderAdvisor();document.querySelectorAll('#view button,#view input,#view select,#view textarea').forEach(el=>el.disabled=true);try{await action();}catch(e){state.error=e.message;if(state.pendingChat)state.advisorDraft=state.pendingChat.message;notify(e.message);}finally{state.busy=false;$('#activity').hidden=true;render();}}
function move(step){const url=new URL(location.href);if(state.activeConversation)url.searchParams.set('session_id',state.activeConversation);else url.searchParams.delete('session_id');url.searchParams.set('view',step===1?'package':step===0?'form':step===3?'verify':step===2?'contact':'checkout');if((step===4&&state.order)||state.correctionOrderId)url.searchParams.set('order_id',state.correctionOrderId||state.order.id);else url.searchParams.delete('order_id');history.replaceState(null,'',url);state.error="";state.step=step;state.reached=Math.max(state.reached,step);render();$('#title').focus({preventScroll:true});}
