  const resizeButton=$('#advisor-resize');
  resizeButton.onpointerdown=e=>{e.preventDefault();resizeButton.setPointerCapture(e.pointerId);const panel=$('#advisor-panel'),rect=panel.getBoundingClientRect(),right=innerWidth<=700?12:28,bottom=innerWidth<=700?94:113,startX=e.clientX,startY=e.clientY,startWidth=rect.width,startHeight=rect.height;resizeButton.onpointermove=move=>{const maxWidth=Math.max(300,innerWidth-right-12),maxHeight=Math.max(280,innerHeight-bottom-12);state.advisorSize={width:Math.round(Math.max(300,Math.min(maxWidth,startWidth+move.clientX-startX))),height:Math.round(Math.max(280,Math.min(maxHeight,startHeight+move.clientY-startY)))};panel.style.width=`${state.advisorSize.width}px`;panel.style.height=`${state.advisorSize.height}px`;};resizeButton.onpointerup=()=>{resizeButton.onpointermove=null;resizeButton.onpointerup=null;};};
  resizeButton.onkeydown=e=>{if(!['ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.key))return;e.preventDefault();const panel=$('#advisor-panel'),rect=panel.getBoundingClientRect(),step=e.shiftKey?40:16;state.advisorSize={width:Math.max(300,Math.min(innerWidth-40,rect.width+(e.key==='ArrowRight'?step:e.key==='ArrowLeft'?-step:0))),height:Math.max(280,Math.min(innerHeight-130,rect.height+(e.key==='ArrowDown'?step:e.key==='ArrowUp'?-step:0)))};panel.style.width=`${state.advisorSize.width}px`;panel.style.height=`${state.advisorSize.height}px`;};
  $('#message').value=state.advisorDraft;$('#message').oninput=e=>state.advisorDraft=e.target.value;
  $('#advisor-panel').onkeydown=e=>{if(e.key==='Escape'){e.preventDefault();toggle(false);}};
  const log=$('.chat-log');log.scrollTop=log.scrollHeight;
