function conversationControls(){if(state.conversationStorage==='unavailable')return '<p class="warning">Saved conversations are unavailable. Check PostgreSQL and refresh.</p>';if(state.conversationStorage!=='postgresql')return '';const active=state.conversations.find(c=>c.id===state.activeConversation);return `<div class="conversation-controls"><div class="conversation-toolbar"><span class="conversation-active" title="${esc(active?.title||tr('Start a conversation','बातचीत शुरू करें'))}">${esc(active?.title||tr('Start a conversation','बातचीत शुरू करें'))}</span><div class="conversation-actions"><button class="history-trigger" type="button" id="conversation-history-toggle" aria-label="${tr('Chat history','चैट इतिहास')}" title="${tr('Chat history','चैट इतिहास')}" aria-controls="conversation-history-panel" aria-expanded="${state.historyOpen}" ${state.busy?'disabled':''}><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M3 12a9 9 0 1 0 2.64-6.36L3 8.3"/><path d="M3 3v5h5M12 7v5l3 2"/></svg><span>${state.conversations.length}</span></button><button class="text-btn" type="button" id="new-conversation" ${state.busy?'disabled':''}>+ ${tr('New chat','नई चैट')}</button></div></div><div id="conversation-history-panel" class="conversation-history-panel" ${state.historyOpen?'':'hidden'}><div class="history-panel-heading"><b>${tr('Chat history','चैट इतिहास')}</b><button class="icon-btn" type="button" id="conversation-history-close" aria-label="${tr('Close history','इतिहास बंद करें')}">×</button></div><div class="conversation-list">${state.conversations.map(c=>`<button type="button" class="conversation-entry ${c.id===state.activeConversation?'selected':''}" data-conversation="${esc(c.id)}" ${state.busy?'disabled':''} aria-current="${c.id===state.activeConversation}"><b data-user-content>${esc(c.title)}</b><small data-user-content>${esc(c.preview)}</small><small>${tr('Updated','अपडेट')}: ${esc(new Date(c.updatedAt||c.createdAt).toLocaleString('en-IN',{timeZone:'Asia/Kolkata',dateStyle:'medium',timeStyle:'short'}))}${c.id===state.activeConversation?` · ${tr('Current chat','वर्तमान चैट')}`:''}</small></button>`).join('')||`<p class="hint">${tr('Your saved chats will appear here.','सेव चैट यहाँ दिखेंगी।')}</p>`}</div>${state.activeConversation?`<button class="text-btn history-delete" id="delete-conversation" type="button" ${state.busy?'disabled':''}>${tr('Delete current chat and its saved KYC files','वर्तमान चैट और इसकी KYC फ़ाइलें हटाएँ')}</button>`:''}<p class="hint history-retention">${tr('Chats are saved to your account. Inactive demo records expire after 7 days.','चैट आपके खाते में सेव हैं। डेमो चैट 7 दिन की निष्क्रियता के बाद हटती हैं।')}</p></div></div>`;}
function syncJourney(c){
  const r=c.requirements||{},p=c.advisorProfile;
  const changed=state.requirementsRevision!==c.revision;
  state.requirementsRevision=c.revision;state.formConfirmed=c.formConfirmed;state.advisorProfile=p;
  state.profile={...state.profile,...p,locations:p?.locations||[],businessName:r.business_name||'',segment:r.business_type||'',employees:r.employee_count??'',sites:r.site_count??'',cityTier:r.city_tier??'',budget:r.budget??'',cameraCount:r.camera_count??'',needs:r.requested_services||[],currentTools:r.current_tools||'',language:state.profile.language,...(changed?{gstin:'',udyam:''}:{gstin:state.profile.gstin,udyam:state.profile.udyam})};
  if(changed){state.gstConsent=false;state.registrationCheck=null;invalidate();state.documents={};state.quote=null;state.reached=Math.min(state.reached,1);if(state.step>1&&state.step<4)state.step=1;}
  if(c.recommendation&&(changed||!state.quote)){state.quote=c.recommendation.quote;state.eligible=c.recommendation.eligibleProducts;state.warnings=c.recommendation.warnings;}
  if(!state.quote&&state.step===1){state.step=0;state.reached=0;}
}
async function newConversation(){const c=await api('/sessions',{requestId:crypto.randomUUID()});state.activeConversation=c.id;state.pendingForm=null;state.historyOpen=false;await loadConversation(c.id,true);}
async function loadConversation(id,newJourney=false){
  const switched=newJourney||state.activeConversation!==id,c=await api('/sessions/'+id);
  if(switched){state.order=null;state.quote=null;state.step=0;state.reached=0;state.requirementsRevision=-1;state.contact={name:'',phone:'',address:''};state.consent=false;state.gstConsent=false;state.registrationCheck=null;state.aiConsent=false;state.documents={};state.kycCaseId=null;state.pendingForm=null;invalidate();}
  state.activeConversation=id;state.historyOpen=false;state.messages=c.messages;state.chatHasMore=c.hasMore;state.advisorOffers=c.offers||[];state.advisorDraft='';state.pendingChat=null;syncJourney(c);if(state.quote)state.reached=Math.max(state.reached,1);state.conversations=(await api('/sessions')).sessions;sessionStorage.setItem('udyam_active_chat',id);
  const url=new URL(location.href);url.searchParams.set('session_id',id);history.replaceState(null,'',url);
}
async function submitSharedForm(){
  const submitted={...state.profile};const signature=JSON.stringify(submitted);
  if(!state.pendingForm||state.pendingForm.signature!==signature)state.pendingForm={signature,requestId:crypto.randomUUID(),revision:state.requirementsRevision};
  const pending=state.pendingForm;
  if(!state.activeConversation){const c=await api('/sessions',{profile:submitted,requestId:pending.requestId});state.activeConversation=c.id;}
  else await api('/sessions/'+state.activeConversation+'/requirements',{profile:submitted,revision:pending.revision,requestId:pending.requestId});
  state.pendingForm=null;await loadConversation(state.activeConversation);await match();move(1);
}
async function navigateJourney(step){if(state.conversationStorage==='postgresql'&&state.activeConversation&&(step===0||step===1)){await loadConversation(state.activeConversation);if(step===1)await match();}move(step);}
async function openAdvisorOffer(offer){
  const enteredBusinessName=($('#business')?.value||state.profile.businessName||'').trim();
  if(state.conversationStorage==='postgresql'&&state.activeConversation){
    await loadConversation(state.activeConversation);
    if(enteredBusinessName&&enteredBusinessName!==state.profile.businessName){
      const saved=await api('/sessions/'+state.activeConversation+'/business-name',{businessName:enteredBusinessName,revision:state.requirementsRevision,requestId:crypto.randomUUID()});
      state.requirementsRevision=saved.revision;state.formConfirmed=saved.formConfirmed;state.advisorProfile=saved.advisorProfile;
      state.profile={...state.profile,...saved.advisorProfile,language:state.profile.language};
    }
  }else readProfile();
  if(!state.profile.businessName)throw new Error('Enter your business name in the form, then find your package.');
  await reprice(offer.items);state.eligible=(await api('/recommend',{...payload(),consent:state.consent||state.gstConsent})).eligibleProducts;move(1);
}
function wireAdvisor(){
  on('#chat-form','submit',e=>{e.preventDefault();if(state.busy)return;const message=$('#message').value.trim();if(!message)return;if(state.conversationStorage==='unavailable'){notify('Saved conversations are unavailable. Check PostgreSQL and refresh.');return;}
    if(state.conversationStorage==='postgresql'){
      state.advisorDraft='';
      run(async()=>{
        if(!state.activeConversation)await newConversation();
        const pending=state.pendingChat?.message===message?state.pendingChat:{message,requestId:crypto.randomUUID()};state.pendingChat=pending;
        const r=await api('/sessions/'+state.activeConversation+'/chat',{...pending,language:state.profile.language});
        state.mode=r.mode;try{await loadConversation(state.activeConversation);}catch(error){state.pendingChat=pending;throw error;}
        if(r.mode==='unavailable'){state.pendingChat=pending;state.advisorDraft=message;}else state.pendingChat=null;
        if(r.proceed&&r.quote)await openAdvisorOffer({items:r.quote.items.map(x=>({productId:x.productId,quantity:x.quantity,...(x.locationId?{locationId:x.locationId}:{})}))});
      });return;
    }
    state.advisorDraft='';readProfile();const profileForChat={...state.profile,businessName:state.profile.businessName||'New business'};if(state.messages.at(-1)?.role!=='user'||state.messages.at(-1)?.content!==message)state.messages.push({role:'user',content:message});run(async()=>{const r=await api('/advisor',{profile:profileForChat,consent:state.consent,messages:state.messages.slice(-12)});state.mode=r.mode;if(r.mode==='unavailable'){state.error=r.reply||advisorErrorText(r.fallbackReason);state.advisorDraft=message;return;}state.messages.push({role:'assistant',content:r.reply});if(r.proposedProfile){state.profile={...r.proposedProfile,businessName:state.profile.businessName};state.quote=null;state.reached=0;invalidate();}if(r.intent!=='question')state.advisorOffers=r.options||[];});
  });
  on('#new-conversation','click',()=>run(newConversation));
  on('#conversation-history-toggle','click',()=>{state.historyOpen=!state.historyOpen;const panel=$('#conversation-history-panel'),button=$('#conversation-history-toggle');panel.hidden=!state.historyOpen;button.setAttribute('aria-expanded',String(state.historyOpen));if(state.historyOpen)$('#conversation-history-close')?.focus();});
  on('#conversation-history-close','click',()=>{state.historyOpen=false;$('#conversation-history-panel').hidden=true;$('#conversation-history-toggle').setAttribute('aria-expanded','false');$('#conversation-history-toggle').focus();});
  document.querySelectorAll('[data-conversation]').forEach(el=>el.onclick=()=>run(()=>loadConversation(el.dataset.conversation)));
  on('#delete-conversation','click',()=>run(async()=>{if(!state.activeConversation)return;await api('/sessions/'+state.activeConversation,undefined,'DELETE');state.activeConversation=null;state.requirementsRevision=0;state.formConfirmed=false;state.quote=null;state.reached=0;state.step=0;state.profile={businessName:'',segment:'',employees:'',sites:'',cityTier:'',budget:'',needs:[],currentTools:'',language:state.profile.language,gstin:'',udyam:''};const url=new URL(location.href);url.searchParams.delete('session_id');history.replaceState(null,'',url);invalidate();state.messages=[];state.advisorOffers=[];state.advisorProfile=null;state.advisorDraft='';state.pendingChat=null;sessionStorage.removeItem('udyam_active_chat');state.conversations=(await api('/sessions')).sessions;}));
  on('#older-messages','click',()=>run(async()=>{const r=await api('/sessions/'+state.activeConversation+'/messages?before='+state.messages[0].id);state.messages=[...r.messages,...state.messages];state.chatHasMore=r.hasMore;}));
  document.querySelectorAll('[data-advisor-offer]').forEach(el=>el.addEventListener('click',()=>run(()=>openAdvisorOffer(state.advisorOffers[Number(el.dataset.advisorOffer)]))));
}
function quoteLineKey(item){return item.productId+(item.locationId?'--'+item.locationId:'');}
function activeAddonLocation(){return state.profile.locations?.find(location=>location.id===state.addonLocationId)||state.profile.locations?.[0];}
function siteProduct(product){return product.unit==='per site'||product.unit==='per camera'||product.requiresOneOf?.length>0;}
function addonOptions(){
 const location=activeAddonLocation();
 return state.eligible.filter(product=>{
  const locationId=location&&siteProduct(product)?location.id:undefined;
  return !state.quote?.items.some(item=>item.productId===product.id&&item.locationId===locationId)
   &&(!locationId||!product.availableLocationIds||product.availableLocationIds.includes(locationId));
 });
}
function locationQuoteSummary(q){
 if(!q.locationTotals)return '';
 return `<section class="location-totals"><h3>${tr('Services by location','स्थान के अनुसार सेवाएँ')}</h3>${q.locationTotals.map(location=>`<div class="review-field"><span data-user-content>${esc(location.name)}${location.city?' · '+esc(location.city):''} · Tier ${location.cityTier}</span><span>${money(location.monthly)} / mo<br><small>${tr('Setup','सेटअप')}: ${money(location.setup)}</small></span></div>`).join('')}<div class="review-field"><span>${tr('Shared services (counted once)','साझा सेवाएँ (एक बार गिनी गईं)')}</span><span>${money(q.sharedMonthly)} / mo</span></div></section>`;
}
function discover(){return `<div class="card"><div class="card-title">${tr('A little about your business','अपने बिज़नेस के बारे में बताएँ')}</div><p class="card-sub">${tr('Use these fields, or ask the advisor for help.','विवरण भरें या सलाहकार की मदद लें।')}</p><form id="profile-form">
  <div class="field-group">${field('business',tr('Business name','बिज़नेस का नाम'),state.profile.businessName,'required maxlength="120" placeholder="Green Leaf Family Clinic"')}</div>
  <div class="field-group"><label class="field-label" for="segment">${tr('Business type','बिज़नेस का प्रकार')}</label><select class="field" id="segment" required><option value="" ${!state.profile.segment?'selected':''} disabled>${tr('Choose a business type','बिज़नेस का प्रकार चुनें')}</option>${Object.entries(segments).map(([key,name])=>`<option value="${key}" ${key===state.profile.segment?'selected':''}>${name}</option>`).join('')}</select></div>
  <div class="grid2"><div>${field('employees',tr('Employees','कर्मचारी'),state.profile.employees,'type="number" min="1" max="10000" required')}</div></div>
  <div class="grid2"><div><label class="field-label" for="tier">${tr('City tier','शहर की श्रेणी')}</label><select class="field" id="tier" required><option value="" ${!state.profile.cityTier?'selected':''} disabled>${tr('Choose a tier','श्रेणी चुनें')}</option><option value="1" ${state.profile.cityTier===1?'selected':''}>Tier 1</option><option value="2" ${state.profile.cityTier===2?'selected':''}>Tier 2</option></select></div><div>${field('budget',tr('Monthly budget (₹)','मासिक बजट (₹)'),state.profile.budget,'type="number" min="1" max="10000000" required')}</div></div>
  <fieldset class="needs"><legend>${tr('What do you need?','आपको क्या चाहिए?')}</legend>${Object.entries(needs).map(([key,name])=>`<label class="need"><input type="checkbox" name="need" value="${key}" ${state.profile.needs.includes(key)?'checked':''}> ${name}</label>`).join('')}</fieldset>
  <div class="field-group" id="camera-count-group" ${state.profile.needs.includes('cctv')?'':'hidden'}>${field('camera-count',tr('Total CCTV cameras','CCTV कैमरों की कुल संख्या'),state.profile.cameraCount??'','type="number" min="1" max="10000" '+(state.profile.needs.includes('cctv')?'required':'disabled'))}<p class="hint">${tr('Enter the number of cameras needed at this business address.','इस बिज़नेस पते पर आवश्यक कैमरों की संख्या बताएँ।')}</p></div>
  <div class="field-group">${field('tools',tr('Current tools or challenges (optional)','अभी के साधन या समस्याएँ (वैकल्पिक)'),state.profile.currentTools,'maxlength="500" placeholder="Mobile hotspot, personal email…"')}</div><button class="btn full" type="submit">${tr('Find my package','मेरा पैकेज खोजें')} →</button></form></div>
`;}
function advisorQuickOptions(){
 const last=state.messages.at(-1);if(last?.role!=='assistant'||state.busy)return '';
 const text=last.content||'';let choices=[];
 if(/Tier 1 or Tier 2|Tier 1.*Tier 2/i.test(text))choices=['Tier 1','Tier 2'];
 else if(/GST.*(?:yes or no|registration\?)/i.test(text))choices=['Yes, I have GST registration','No GST registration'];
 else if(/Would you like postpaid/i.test(text))choices=['Yes, postpaid connections','Show other eligible services'];
 else if(state.advisorOffers.length)choices=['Explain the prices','Show a lower-cost option','I want to change my requirements'];
 return choices.length?`<div class="advisor-quick-options">${choices.map(choice=>`<button type="button" class="text-btn" data-chat-choice="${esc(choice)}">${esc(choice)}</button>`).join('')}</div>`:'';
}
document.addEventListener('click',event=>{const choice=event.target.closest('[data-chat-choice]');if(!choice)return;const input=document.querySelector('#message');if(input){input.value=choice.dataset.chatChoice;document.querySelector('#chat-form')?.requestSubmit();}});
function advisorView(){return `<section class="card chat-card"><div class="reco-head"><div class="card-title">✳ ${tr('Your business advisor','आपका बिज़नेस सलाहकार')}</div><span class="badge">${state.mode==='ai_configured'||state.mode==='ai'?'AI':state.mode==='unavailable'?'UNAVAILABLE':'GUIDED'}</span></div><p class="hint">${tr('Ask about needs, budget or your package. Keep document IDs and phone numbers out of this chat.','ज़रूरतों और बजट के बारे में पूछें। यहाँ पहचान नंबर या फ़ोन नंबर न लिखें।')}</p>${state.error?`<div class="warning" role="alert">${esc(state.error)}</div>`:''}${state.busy?`<p role="status">${tr('Thinking…','सोच रहा है…')}</p>`:''}${state.chatHasMore?`<button class="text-btn" type="button" id="older-messages">${tr('Load older messages','पुराने संदेश देखें')}</button>`:''}<div class="chat-log" role="log" aria-live="polite">${state.messages.map(m=>`<div class="bubble ${m.role}">${esc(m.content)}</div>`).join('')||`<div class="bubble assistant">${tr('What would you like to improve for your business?','आप अपने बिज़नेस में क्या सुधार चाहते हैं?')}</div>`}</div>${advisorQuickOptions()}<form id="chat-form" class="chat-compose"><label class="sr-only" for="message">Advisor message</label><input class="field" id="message" maxlength="2000" required value="${esc(state.advisorDraft)}" placeholder="${tr('I need internet and email for 5 people…','5 लोगों के लिए इंटरनेट और ईमेल चाहिए…')}"><button class="btn" type="submit">${tr('Send','भेजें')}</button></form>${state.advisorOffers.map((o,i)=>`<div class="price-box"><span>${esc(o.label)}<br><small>${o.quote.items.map(x=>(x.locationName?esc(x.locationName)+' · ':'')+esc(x.name)+' × '+x.quantity+' — '+esc(x.reason||'')).join('<br>')}</small><br>${moneyRange(o.quote.monthly,o.quote.monthlyMax)} / month · setup ${money(o.quote.setup)}</span><button class="btn" type="button" data-advisor-offer="${i}">${tr('Review package','पैकेज देखें')}</button></div>`).join('')}</section>`;}

function registrationView(){
 const check=state.registrationCheck,needsCheck=state.warnings.some(w=>/valid active GSTIN/.test(w));
 if(check?.status==='matched')return `<div class="status-card" role="status"><b>${tr('GST registry lookup completed','GST रजिस्ट्री जाँच पूरी हुई')}</b><p>${esc(check.maskedGstin)}</p><p>${esc(check.message)}</p></div>`;
 if(!needsCheck&&!check)return '';
 return `<section class="status-card"><h3>${tr('Check GST eligibility','GST पात्रता जाँचें')}</h3><p>${tr('Selected services require active GST registration. Enter your GSTIN here to check the supplied mock registry and update this package.','चुनी सेवाओं के लिए सक्रिय GST पंजीकरण चाहिए। नमूना रजिस्ट्री में जाँच के लिए यहाँ GSTIN दें।')}</p>${check?`<p class="warning" role="alert">${esc(check.message)}</p>`:''}<form id="package-gst-form"><div class="field-group"><label class="field-label" for="package-gstin">GSTIN</label><input class="field" id="package-gstin" name="gstin" type="text" minlength="15" maxlength="15" required autocomplete="off" autocapitalize="characters" spellcheck="false" placeholder="15-character GSTIN"></div><label class="checkbox"><input id="package-gst-consent" type="checkbox" required>${tr('I consent to checking this GSTIN and business name against the supplied mock registry for package eligibility.','मैं पैकेज पात्रता के लिए GSTIN और बिज़नेस नाम की नमूना रजिस्ट्री से जाँच की अनुमति देता/देती हूँ।')}</label><button class="btn full" type="submit">${tr('Check GSTIN and update package','GSTIN जाँचें और पैकेज अपडेट करें')}</button></form><p class="hint">${tr('This is a preliminary mock registry lookup. You will separately consent to certificate processing during KYC.','यह प्रारंभिक नमूना रजिस्ट्री जाँच है। KYC में प्रमाणपत्र पढ़ने के लिए अलग अनुमति ली जाएगी।')}</p></section>`;
}
function packageView(){const q=state.quote;return `<div class="card"><div class="reco-head"><div class="card-title">${tr('Your recommended setup','आपका सुझाया पैकेज')}</div><span class="badge">CATALOGUE</span></div><p class="card-sub">${tr('Matched to your needs, size, location and budget.','आपकी ज़रूरतों, आकार, शहर और बजट के अनुसार।')}</p>${[...new Set(state.warnings)].map(w=>`<div class="warning">${esc(w)}</div>`).join('')}${registrationView()}
  ${q?q.items.toSorted((a,b)=>["requested","supporting","addon"].indexOf(a.selectionType)-["requested","supporting","addon"].indexOf(b.selectionType)).map((x,index,rows)=>`${index===0||rows[index-1].selectionType!==x.selectionType?`<h3>${x.selectionType==="addon"?tr("Selected add-ons","चुनी अतिरिक्त सेवाएँ"):x.selectionType==="supporting"?tr("Required supporting services","ज़रूरी सहायक सेवाएँ"):tr("Your requested services","आपकी अनुरोधित सेवाएँ")}</h3>`:""}<div class="product"><span class="product-icon">✳</span><div class="product-info"><div class="product-name">${esc(x.name)}</div>${x.locationName?`<div class="location-label" data-user-content>${esc(x.locationName)} · Tier ${x.cityTier}</div>`:''}<div class="product-desc">${esc(x.description)}</div><div class="recommendation-reason">${esc(x.reason||"")}</div><div class="hint">${money(x.unitPrice)} / ${esc(x.unit)} · ${x.contractMonths} mo minimum<br>${tr("One-time setup for this item","इस सेवा का एक बार का सेटअप")}: ${money(x.setup)}</div></div><div class="product-price">${money(x.monthly)}<small>/ month</small><small>${tr("Catalogue range","कैटलॉग सीमा")}: ${moneyRange(x.monthly,x.monthlyMax)}</small><label class="sr-only" for="qty-${esc(quoteLineKey(x))}">Quantity for ${esc(x.name)}${x.locationName?' — '+esc(x.locationName):''}</label><input class="quantity" id="qty-${esc(quoteLineKey(x))}" data-quantity="${esc(quoteLineKey(x))}" type="number" min="1" max="10000" value="${x.quantity}" ${x.unit==='per site'?'readonly':''}><button class="remove text-btn" data-remove="${esc(quoteLineKey(x))}" aria-label="Remove ${esc(x.name)}${x.locationName?' — '+esc(x.locationName):''}">${tr('Remove','हटाएँ')}</button></div></div>`).join(''):`<div class="warning">${tr('Your requested services are saved. A complete package is not available yet. Review the restrictions above, then choose Change business needs to update your selection.','आपकी अनुरोधित सेवाएँ सेव हैं। अभी पूरा पैकेज उपलब्ध नहीं है। ऊपर दी गई शर्तें देखें और ज़रूरतें बदलें चुनें।')}</div>`}
  ${q?`${state.profile.locations?.length?`<div class="field-group"><label class="field-label" for="addon-location">${tr("Location for site-based services","स्थान आधारित सेवाओं की शाखा")}</label><select class="field" id="addon-location">${state.profile.locations.map(location=>`<option value="${esc(location.id)}" ${activeAddonLocation()?.id===location.id?"selected":""}>${esc(location.name)} · Tier ${location.cityTier}</option>`).join('')}</select></div>`:""}${q?button("update-quantities",tr("Update quantities","संख्या के अनुसार कीमत बदलें"),true):""}<div class="grid2"><div><label class="field-label" for="addon">${tr('Add another eligible service','अन्य उपलब्ध सेवा जोड़ें')}</label><select class="field" id="addon"><option value="">${tr('Choose a service','सेवा चुनें')}</option>${addonOptions().map(p=>`<option value="${p.id}">${esc(p.name)} — ${moneyRange(p.price,p.maxPrice)}/${esc(p.unit)}</option>`).join('')}</select></div><div class="add-action"><button class="text-btn" id="add">+ ${tr('Add service','सेवा जोड़ें')}</button></div></div>`:""}
  ${q?`${locationQuoteSummary(q)}${q.breakdown?`<div class="quote-details"><span>${tr("Requested services","अनुरोधित सेवाएँ")}: <b>${money(q.breakdown.requested.monthly)} / mo</b></span><span>${tr("Required supporting services","ज़रूरी सहायक सेवाएँ")}: <b>${money(q.breakdown.supporting.monthly)} / mo</b></span><span>${tr("Selected add-ons","चुनी अतिरिक्त सेवाएँ")}: <b>${money(q.breakdown.addon.monthly)} / mo</b></span></div>`:""}<div class="price-box"><span>${tr('Fixed demo monthly quote','डेमो की तय मासिक कीमत')}<br>${q.contractMonths} ${tr('month minimum commitment','महीने न्यूनतम अवधि')}</span><strong>${money(q.checkoutMonthly??q.monthly)}<small> / mo</small></strong></div><p class="hint">${tr('Catalogue range','कैटलॉग सीमा')}: ${moneyRange(q.monthly,q.monthlyMax)}<br>${esc(q.pricingNote||'')}</p><div class="quote-details"><span>${tr('One-time setup','एक बार का सेटअप')}: <b>${money(q.setup)}</b></span><span>${tr('Typical installation','सामान्य इंस्टॉलेशन')}: <b>${q.installDays} ${tr('days','दिन')}</b></span></div><p class="hint">${esc(q.taxNote)} Availability and installation need confirmation.</p>${q.warnings.map(w=>`<div class="warning">${esc(w)}</div>`).join('')}${button('checkout',tr('Continue with this package','इस पैकेज के साथ आगे बढ़ें'))}`:''}${button('back',tr('← Change business needs','← ज़रूरतें बदलें'),true)}</div>`;}
function contactView(){return `<div class="card"><div class="card-title">${tr('Order contact','ऑर्डर के लिए संपर्क')}</div><p class="card-sub">${tr('Used for verification and arranging your services.','जाँच और चुनी सेवाओं की व्यवस्था के लिए।')}</p><form id="contact-form"><div class="field-group">${field('owner',tr('Owner / authorized signatory name','मालिक / अधिकृत व्यक्ति का नाम'),state.contact.name,'required maxlength="120" autocomplete="name"')}</div><div class="field-group">${field('phone',tr('Indian mobile number','भारतीय मोबाइल नंबर'),state.contact.phone,'required type="tel" maxlength="20" autocomplete="tel" placeholder="98765 43210"')}</div><div class="field-group"><label class="field-label" for="address">${tr('Full installation address','इंस्टॉलेशन का पूरा पता')}</label><textarea class="field" id="address" required minlength="10" maxlength="400" rows="3" autocomplete="street-address">${esc(state.contact.address)}</textarea></div><button class="btn full" type="submit">${tr('Continue to verification','दस्तावेज़ जाँच के लिए आगे बढ़ें')} →</button></form></div>`;}
const kycLabels={matched:'Verified field match',mismatch_detected:'Mismatch detected',registration_not_found:'Registration not found',invalid_registration_format:'Invalid registration format',invalid_checksum:'Invalid checksum',cancelled_registration:'Cancelled registration',missing_document:'Missing document',outdated_document:'Outdated document',extraction_failed:'Extraction failed',invalid_specimen:'Invalid specimen',manual_review_required:'Manual review required',unable_to_verify:'Unable to verify',not_required:'Not required',not_extracted:'Not checked yet'};
function kycResultsView(){const v=state.verification,hasFields=v.documents.some(d=>d.reviewFields&&Object.keys(d.reviewFields).length);return `<section class="verification-results" aria-live="polite"><h3>${esc({checks_passed:'Checks passed',action_required:'Action required',manual_review_required:'Manual review required',unable_to_verify:'Unable to verify'}[v.overallStatus]||'Action required')}</h3>${Number.isFinite(v.processingMs)?`<p class="hint">${tr("Checks completed in","जाँच का समय")} ${(v.processingMs/1000).toFixed(1)} ${tr("seconds","सेकंड")}. ${tr("Larger or unclear scans can take longer.","बड़े या अस्पष्ट स्कैन में अधिक समय लग सकता है।")}</p>`:""}<p class="hint">Reader: ${esc(translateMessage(v.extractionMode,state.profile.language))} · Storage: ${esc(translateMessage(v.storageMode||state.kycStorage,state.profile.language))} · Reference date: 15 July 2026${v.caseId?' · Saved KYC case '+esc(v.caseId.slice(0,8)):''}</p>${v.documents.map(d=>`<section class="kyc-result"><div class="document-status"><b>${esc(docNames[d.kind])}</b><span class="badge">${esc(kycLabels[d.status]||d.status)}</span></div><p class="hint">${d.uploaded?'Uploaded'+(d.filename?' · '+esc(d.filename):'')+(d.version?' · version '+d.version:''):d.required?'Upload needed':'Optional for this application'}<br>Extraction: ${esc(translateMessage(d.extractionStatus,state.profile.language))}${d.reader?' · Method: '+esc(d.reader):''}${Number.isFinite(d.confidence)?' · OCR confidence '+d.confidence+'%':''}${d.registry?' · Mock registry: '+esc(d.registry.status)+(d.registry.registrationStatus?' ('+esc(d.registry.registrationStatus)+')':''):''}${d.ageDays!==undefined?' · Document age: '+Math.floor(d.ageDays)+' days':''}</p>${d.reviewFields?`<div class="review-fields">${Object.entries(d.reviewFields).map(([key,value])=>`<div class="review-field"><span>${esc(reviewFieldNames[key]||key)}</span><span data-user-content>${esc(value)}</span></div>`).join('')}</div>`:''}${(d.findings||[]).map(f=>`<div class="warning"><b>${esc(f.code.replaceAll('_',' '))}</b><br>${esc(f.message)}<br><strong>Next step:</strong> ${esc(f.action)}</div>`).join('')}${(d.findings||[]).length||d.required&&!d.uploaded?`<button class="text-btn" type="button" data-replace-doc="${esc(d.kind)}">${d.uploaded?tr("Choose a replacement for this document","इस दस्तावेज़ की नई प्रति चुनें"):tr("Upload this document","यह दस्तावेज़ अपलोड करें")}</button><br>`:""}${d.documentId?`<button class="text-btn" type="button" data-preview-saved="${esc(d.documentId)}">Preview document</button> · <a class="text-btn" href="/api/kyc/documents/${esc(d.documentId)}/download">Download original</a>`:''}</section>`).join('')}${v.checks.map(c=>`<p class="${/unable to verify/i.test(c)?"hint":"check-result"}">${/unable to verify/i.test(c)?"":"✓ "}${esc(c)}</p>`).join('')}${v.reviewerDecision?`<div class="status-card"><b>Simulated reviewer: ${esc(v.reviewerDecision.decision)}</b><p data-user-content>${esc(v.reviewerDecision.comment)}</p><small>${esc(new Date(v.reviewerDecision.decidedAt).toLocaleString('en-IN',{timeZone:'Asia/Kolkata'}))}</small></div>`:''}${hasFields?`<label class="checkbox"><input id="fields-reviewed" type="checkbox" ${state.fieldsReviewed?'checked':''}>${tr('I reviewed the extracted fields. I will correct details or replace only the affected file if something is wrong.','मैंने निकाले गए विवरण देख लिए हैं। गलत विवरण या केवल संबंधित फ़ाइल बदलूँगा/बदलूँगी।')}</label>`:''}<p class="hint">${esc(v.note)}</p>${v.caseId&&v.id&&v.status==="review_required"?(v.reviewRequest?.status==="pending"?`<p class="status-card">${tr("Review requested in the local staff workspace. Refresh saved KYC results to check for a reply.","स्थानीय कर्मचारी पेज पर समीक्षा का अनुरोध सेव है। जवाब देखने के लिए सेव KYC परिणाम रीफ्रेश करें।")}</p>`:button("request-kyc-review",tr("Request assisted review","सहायता समीक्षा का अनुरोध करें"),true)):""}${state.correctionOrderId?'':button('review-services',tr('Review services available for my registration','पंजीकरण के अनुसार सेवाएँ देखें'),true)}${v.id?state.correctionOrderId?(v.status==='passed'?button('place-order',tr('Submit corrected documents','सुधारे दस्तावेज़ भेजें')):'<p class="warning">Resolve the document checks before submitting corrections.</p>'):button('place-order',v.status==='passed'?tr('Place order','ऑर्डर करें'):tr('Save order for assisted review','समीक्षा के लिए ऑर्डर सेव करें')):'<p class="warning">Files or details changed. Run checks again before continuing.</p>'}${state.kycCaseId?'<button type="button" class="text-btn secondary" id="refresh-kyc">Refresh saved KYC results</button><button type="button" class="text-btn secondary" id="delete-kyc">Delete saved KYC documents and case</button>':''}</section>`;}
function kycPrivacy(){return state.kycStorage==='encrypted_local'?tr('With your consent, documents are read for this application and checked against the supplied mock registries. Uploads and extracted fields are encrypted locally for up to 7 days with this browser session. Replace individual files, request simulated review, or delete the saved KYC case here. This is not government authentication.','आपकी अनुमति से दस्तावेज़ पढ़कर नमूना रजिस्ट्रियों से जाँच करते हैं। फ़ाइलें और निकाले गए विवरण स्थानीय रूप से एन्क्रिप्ट होकर 7 दिन तक रहते हैं। आप संबंधित फ़ाइल बदल सकते हैं या KYC केस हटा सकते हैं। यह सरकारी प्रमाणीकरण नहीं है।'):tr('This session supports temporary document reading only. Original files are not saved for later previews or reviewer history. Extracted fields are shown for you to check. This is not government authentication.','इस सत्र में दस्तावेज़ केवल अस्थायी रूप से पढ़े जाते हैं। मूल फ़ाइलें बाद के प्रीव्यू या समीक्षा के लिए सेव नहीं होतीं। निकाले गए विवरण जाँचने के लिए दिखते हैं। यह सरकारी प्रमाणीकरण नहीं है।');}
function verifyView(){return `${state.correctionOrderId?button('back-to-order',tr('Back to order tracker','ऑर्डर ट्रैकर पर लौटें'),true):''}<div class="card"><div class="card-title">${tr('You control your information','आपकी जानकारी पर आपका नियंत्रण')}</div><div class="status-card">${kycPrivacy()}</div>
<label class="checkbox"><input id="consent" type="checkbox" ${state.consent?'checked':''}>${tr('I consent to document processing and, when configured, encrypted local retention for up to 7 days under my browser or signed-in account. Unchecking deletes the saved KYC case; saved order snapshots remain.','मैं इस आवेदन के लिए दस्तावेज़ पढ़ने और स्थानीय एन्क्रिप्टेड संग्रह की अनुमति देता/देती हूँ। अनुमति हटाने पर KYC केस हटेगा; सेव ऑर्डर बना रहेगा।')}</label>
<div class="field-group"><label class="field-label" for="reader">${tr('Document reader','दस्तावेज़ रीडर')}</label><select class="field" id="reader" ${!state.consent?'disabled':''}><option value="local" ${state.extractionMethod==='local'?'selected':''}>${tr('Automatic local PDF / image reader','स्वचालित स्थानीय PDF / तस्वीर रीडर')}</option><option value="manual" ${state.extractionMethod==='manual'?'selected':''}>${tr('Fallback: simulated assisted review','वैकल्पिक: नमूना सहायता समीक्षा')}</option><option value="ai" ${!state.externalImageReading?'disabled':''} ${state.extractionMethod==='ai'?'selected':''}>External OpenAI reader (separate consent)</option></select><p class="hint">PDF text is read when available; scanned PDFs and images use installed English OCR. No cloud upload in local mode.</p></div><label class="checkbox" ${state.extractionMethod!=='ai'?'hidden':''}><input id="ai-consent" type="checkbox" ${state.aiConsent?'checked':''} ${!state.consent?'disabled':''}>I separately consent to sending document pages to the configured OpenAI reader.</label>
<div class="field-group">${field('gstin','GSTIN (optional; can be extracted from certificate)',state.profile.gstin,'maxlength="15" autocomplete="off"')}</div><div class="field-group">${field('udyam','Udyam number (optional; can be extracted from certificate)',state.profile.udyam,'maxlength="19" autocomplete="off"')}</div><p class="hint">No GST or Udyam? Leave the numbers and those certificates empty. GST is enforced only for products that require it. Address proof and signatory identification support this application.</p>
<div class="documents">${Object.entries(docNames).map(([kind,name])=>`<div class="document-item"><label><span>${name}</span><input type="file" data-doc="${kind}" accept="image/png,image/jpeg,application/pdf,.pdf" ${!state.consent?'disabled':''}></label><small>${state.documents[kind]?tr('Selected:','चुनी फ़ाइल:')+' <span data-user-content>'+esc(state.documents[kind].name)+'</span>':'JPEG / PNG / PDF · up to 2 MB · 4 pages per PDF'}</small>${state.documents[kind]?`<div><button type="button" class="text-btn" data-preview="${kind}">Preview</button> · <button type="button" class="text-btn" data-clear-doc="${kind}">Remove / replace this file</button></div>`:''}</div>`).join('')}</div><p class="hint">Dates are checked against 15 July 2026. Address proof must be no older than 90 days. Selecting a file does not verify it.</p>${button('verify',tr('Run checks','जाँच शुरू करें'))}${state.verification?kycResultsView():''}</div>`;}
function invalidateDocument(kind){state.fieldsReviewed=false;state.requestKey=crypto.randomUUID();if(state.verification){state.verification={...state.verification,id:null,status:'review_required',overallStatus:'action_required',checks:[],issues:['File changed. Run checks again.'],documents:state.verification.documents.map(d=>d.kind===kind?{...d,status:'not_extracted',extractionStatus:'not_extracted',uploaded:!!state.documents[kind],reviewFields:null,documentId:null,findings:[{code:'not_extracted',message:'This file changed after the previous checks.',action:'Run checks again.'}]}:d)};}}
async function loadKycCase(restoreContact=false){
 const query=state.activeConversation?'?journeyId='+state.activeConversation:'';
 const list=await api('/kyc/cases'+query);const c=list.cases[0];if(!c)return;
 const full=await api('/kyc/cases/'+c.id);state.kycCaseId=c.id;state.consent=true;state.verification={...c.result,id:c.verificationId,storageMode:'encrypted_local'};state.fieldsReviewed=false;
 if((c.result.requirementsRevision!==null&&c.result.requirementsRevision!==undefined&&c.result.requirementsRevision!==state.requirementsRevision)||(!restoreContact&&JSON.stringify(state.contact)!==JSON.stringify(full.contact))){state.verification.id=null;state.verification.status='review_required';state.verification.overallStatus='action_required';}
 state.documents=Object.fromEntries(c.result.documents.filter(d=>d.uploaded&&d.documentId).map(d=>[d.kind,{name:d.filename||docNames[d.kind],documentId:d.documentId}]));
 if(restoreContact)state.contact=full.contact;
}
async function previewDocument(kind,id){
 const dialog=$('#document-preview'),img=$('#document-preview-image');img.removeAttribute('src');$('#document-preview-status').textContent=tr('Preparing private preview…','निजी प्रीव्यू तैयार हो रहा है…');dialog.showModal();
 try{let src;if(id)src='/api/kyc/documents/'+id+'/preview';else{const d=state.documents[kind];if(d.documentId)src='/api/kyc/documents/'+d.documentId+'/preview';else if(d.dataUrl.startsWith('data:image/'))src=d.dataUrl;else src=(await api('/kyc/preview',{consent:state.consent,document:{kind,dataUrl:d.dataUrl}})).preview;}
  img.onload=()=>$('#document-preview-status').textContent=tr('Private document preview. PDF previews show the first page.','निजी दस्तावेज़ प्रीव्यू। PDF का पहला पन्ना दिखाया जाता है।');img.onerror=()=>$('#document-preview-status').textContent=tr('No readable preview. Replace this document or download the original.','पढ़ने योग्य प्रीव्यू नहीं है। दस्तावेज़ बदलें या मूल फ़ाइल डाउनलोड करें।');img.src=src;
 }catch(e){$('#document-preview-status').textContent=translateMessage(e.message,state.profile.language);}
}
function savedOrderButtons(){return state.orders.map(o=>`<button type="button" class="text-btn saved-order" data-order="${esc(o.id)}"><b>${esc(o.id)}</b><br><small>${esc(translateMessage(o.status,state.profile.language))} · ${esc(new Date(o.createdAt).toLocaleString(state.profile.language==='hi'?'hi-IN':'en-IN',{timeZone:'Asia/Kolkata'}))}</small></button>`).join('');}
function orderList(){return state.orders.length?`<details class="order-list"><summary>${tr('Saved orders in this browser','इस ब्राउज़र में सेव ऑर्डर')} (${state.orders.length})</summary>${savedOrderButtons()}</details>`:'';}
async function openSavedOrder(id){
 const order=await api('/orders/'+id);
 const journey=order.quote.sessionId||null;
 if(journey&&state.conversationStorage==='postgresql'){
  try{await loadConversation(journey);}catch{state.messages=[];state.advisorOffers=[];}
 }else {state.messages=[];state.advisorOffers=[];}
 state.activeConversation=journey;
 if(journey)sessionStorage.setItem('udyam_active_chat',journey);else sessionStorage.removeItem('udyam_active_chat');
 state.correctionOrderId=null;state.order=order;state.profile={...order.profile,language:preferredLanguage(),gstin:'',udyam:''};state.quote=order.quote;state.contact=order.contact;state.documents={};invalidate();move(4);
}
function wireSavedOrders(root){root.querySelectorAll('[data-order]').forEach(el=>el.addEventListener('click',()=>{if(state.busy)return;$('#orders-dialog').close();run(()=>openSavedOrder(el.dataset.order));}));}
async function showSavedOrders(){
 state.orders=(await api('/orders')).orders;
 $('#orders-dialog-list').innerHTML=savedOrderButtons()||`<p>${state.customerSignedIn?tr('No saved orders for this account. Create an order or link records from the original browser session.','इस खाते में सेव ऑर्डर नहीं हैं। नया ऑर्डर करें या मूल ब्राउज़र सत्र के रिकॉर्ड जोड़ें।'):tr('No saved orders in this browser session.','इस ब्राउज़र सत्र में कोई सेव ऑर्डर नहीं है।')}</p>`;
 wireSavedOrders($('#orders-dialog'));localizePage($('#orders-dialog'),state.profile.language);$('#orders-dialog').showModal();
}
async function openOrderCorrections(){
 const order=state.order;if(!order?.verification.caseId)throw new Error('No saved KYC case is linked to this order.');
 const c=await api('/kyc/cases/'+order.verification.caseId);
 state.correctionOrderId=order.id;state.kycCaseId=c.id;state.verification={...c.result,id:c.verificationId,storageMode:'encrypted_local'};state.consent=true;state.fieldsReviewed=false;
 state.contact=order.contact;state.profile={...order.profile,language:preferredLanguage(),gstin:'',udyam:''};state.quote=order.quote;
 state.documents=Object.fromEntries(c.result.documents.filter(d=>d.uploaded&&d.documentId).map(d=>[d.kind,{name:d.filename||docNames[d.kind],documentId:d.documentId}]));move(3);
}
function reviewerMessages(o){const review=o.kycReview;if(!review?.decisions?.length)return '';return `<section class="customer-review"><h3>${tr('Document review messages','दस्तावेज़ समीक्षा संदेश')}</h3>${!review.pendingCorrection&&o.verification.addressedDecisionId?`<p class="check-result">${tr('Your corrected documents were submitted for this order. Earlier messages remain below.','इस ऑर्डर के सुधारे दस्तावेज़ भेज दिए गए हैं। पिछले संदेश नीचे हैं।')}</p>`:''}${review.decisions.map(d=>`<div class="status-card"><b>${esc(translateMessage(d.decision,state.profile.language))}</b><p data-user-content>${esc(d.comment)}</p><small>${esc(new Date(d.decidedAt).toLocaleString('en-IN',{timeZone:'Asia/Kolkata'}))}</small></div>`).join('')}${review.canCorrect?button('correct-documents',tr('Review / correct documents','दस्तावेज़ देखें / सुधारें'),true):''}</section>`;}
function trackView(){
  const o=state.order;
  if(!o)return `<div class="card">${tr('No order selected.','कोई ऑर्डर चुना नहीं गया।')}${button('new-order',tr('Start a new setup','नया सेटअप शुरू करें'))}${orderList()}</div>`;
  const estimate=new Date(o.createdAt);estimate.setDate(estimate.getDate()+Number(o.quote.installDays||0));
  const estimateText=Number.isFinite(+estimate)?estimate.toLocaleDateString(state.profile.language==='hi'?'hi-IN':'en-IN',{timeZone:'Asia/Kolkata'}):tr('Not available','उपलब्ध नहीं');
  const latestEvent=o.events.at(-1), latestDate=latestEvent?.expectedDate;
  const latestAt=new Date(latestEvent?.occurredAt||o.createdAt);
  const latestAtText=Number.isFinite(+latestAt)?latestAt.toLocaleString(state.profile.language==='hi'?'hi-IN':'en-IN',{timeZone:'Asia/Kolkata',dateStyle:'medium',timeStyle:'short'}):'';
  const passed=o.verification.status==='passed',status=o.status;
  const scheduled=['installation_scheduled','installation_in_progress','activation_pending','installed','activated'].includes(status),installed=['installed','activated'].includes(status),activated=status==='activated';
  const statusLabel={ready_for_scheduling:tr('READY FOR SCHEDULING','शेड्यूलिंग के लिए तैयार'),installation_scheduled:tr('INSTALLATION SCHEDULED · DEMO','इंस्टॉलेशन तय · डेमो'),installed:tr('INSTALLED · DEMO','इंस्टॉल हुआ · डेमो'),activated:tr('ACTIVATED · DEMO','सक्रिय · डेमो'),review_required:tr('REVIEW REQUIRED','समीक्षा आवश्यक')}[status]||esc(status.replaceAll('_',' ').toUpperCase());
  const pending={
    ready_for_scheduling:'Operations will confirm an installation date.',
    installation_scheduled:'Check the expected date below. Operations will record when installation begins.',
    installation_in_progress:'Installation is in progress.',
    installed:'Installation is complete. Activation is pending.',
    activation_pending:'Installation is complete. Activation is pending.',
    activated:'Activation completed in the staff demo.',
    order_cancelled:'This order is cancelled.',
    review_required:'Review the KYC messages and submit the requested corrections.'
  };
  return `<div class="card"><span class="badge">${statusLabel}</span><h2 data-user-content>${esc(o.profile.businessName)}</h2><p class="order-id">${esc(o.id)}</p><p class="hint">${esc(new Date(o.createdAt).toLocaleString(state.profile.language==='hi'?'hi-IN':'en-IN',{timeZone:'Asia/Kolkata'}))}</p>
  <div class="timeline"><div class="timeline-item done"><b>${tr('Quote accepted','कोटेशन स्वीकार हुआ')}</b><small>${tr('Order saved','ऑर्डर सेव हुआ')}</small></div><div class="timeline-item ${passed?'done':'attention'}"><b>${tr('Business verification','बिज़नेस जाँच')}</b><small>${passed?tr('Checks passed','जाँच सफल'):tr('Needs manual review','मैनुअल समीक्षा चाहिए')}</small></div><div class="timeline-item ${scheduled?'done':''}"><b>${tr('Installation','इंस्टॉलेशन')}</b><small>${scheduled?tr('Scheduled in demo','डेमो में शेड्यूल हुआ'):tr('Not scheduled yet','अभी शेड्यूल नहीं हुआ')}</small></div><div class="timeline-item ${activated?'done':''}"><b>${tr('Activation','सेवा शुरू')}</b><small>${activated?tr('Simulated as complete','डेमो में पूरा दिखाया'):tr('Waiting for installation','इंस्टॉलेशन की प्रतीक्षा')}</small></div></div>
  <div class="status-card"><b>${tr('Pending action','बाकी काम')}:</b> ${esc(pending[status]||status)}<br><b>${tr('Estimated installation date','इंस्टॉलेशन की अनुमानित तारीख')}:</b> ${esc(o.events.findLast(e=>e.expectedDate)?.expectedDate||estimateText)} (${o.quote.installDays} ${tr('typical days; estimate only','सामान्य दिन; केवल अनुमान')}).</div>
  <div class="price-box"><span>${tr('Fixed demo monthly quote','डेमो की तय मासिक कीमत')}</span><strong>${money(o.quote.checkoutMonthly??o.quote.monthly)}<small> / mo</small></strong></div><p class="hint">${tr('Catalogue range','कैटलॉग सीमा')}: ${moneyRange(o.quote.monthly,o.quote.monthlyMax)}<br>${esc(o.quote.pricingNote||'Historic order: catalogue minimum displayed as the demo monthly amount.')}</p><p class="hint">${tr('One-time setup','एक बार का सेटअप')}: ${money(o.quote.setup)} · ${o.quote.contractMonths} ${tr('month minimum','महीने न्यूनतम')}. ${tr('Taxes excluded. No real installation appointment is booked.','कर अलग हैं। असली इंस्टॉलेशन अपॉइंटमेंट बुक नहीं है।')}</p>
  <section class="latest-order-update" aria-live="polite"><div class="latest-order-update-head"><b>${tr('Latest order update','ऑर्डर का नया अपडेट')}</b><span id="poll-status" role="status">${tr('Updates every 10 seconds','हर 10 सेकंड में अपडेट')}</span></div><p>${esc(latestEvent?.detail||o.status.replaceAll('_',' '))}</p>${latestDate?`<div class="installation-date"><span>${tr('Expected installation date','अनुमानित इंस्टॉलेशन तारीख')}</span><strong>${esc(new Date(`${latestDate}T00:00:00`).toLocaleDateString(state.profile.language==='hi'?'hi-IN':'en-IN',{day:'numeric',month:'long',year:'numeric'}))}</strong><small>${tr('Estimate only · provider confirmation is pending','केवल अनुमान · सेवा प्रदाता की पुष्टि बाकी है')}</small></div>`:''}<small class="latest-order-updated">${tr('Updated','अपडेट हुआ')}${latestAtText?` · ${esc(latestAtText)}`:''}</small></section>
  ${locationQuoteSummary(o.quote)}${reviewerMessages(o)}
  ${(o.verification.issues||[]).map(x=>`<p class="warning">${esc(x)}</p>`).join('')}
  ${(o.events||[]).length?`<details class="event-history"><summary>${tr('Order activity','ऑर्डर गतिविधि')}</summary>${o.events.map(event=>`<div class="event-row"><b>${esc(event.detail)} ${esc(event.expectedDate||"")}</b><small>${esc(new Date(event.occurredAt).toLocaleString(state.profile.language==='hi'?'hi-IN':'en-IN',{timeZone:'Asia/Kolkata'}))}</small></div>`).join('')}</details>`:''}
  <section class="help-request"><h3>${tr('Need help with this order?','इस ऑर्डर में मदद चाहिए?')}</h3><p class="hint">${tr('Staff replies appear here automatically. Requests stay in this local demo; no email or WhatsApp is sent. Do not include ID numbers.','कर्मचारी का जवाब ऑर्डर स्थिति रीफ्रेश करने पर यहाँ दिखेगा। अनुरोध स्थानीय डेमो में रहता है; ईमेल या WhatsApp नहीं भेजा जाता। पहचान नंबर न लिखें।')}</p><form id="support-form"><label class="field-label" for="support-topic">${tr('What do you need help with?','किस विषय में मदद चाहिए?')}</label><select id="support-topic" class="field"><option value="Installation or activation">Installation or activation</option><option value="KYC review">KYC review</option><option value="Quote question">Quote question</option><option value="Other">Other</option></select><label class="field-label" for="support-message">${tr('Message','संदेश')}</label><textarea id="support-message" class="field" rows="3" maxlength="500" required placeholder="${tr('Briefly describe the issue','समस्या संक्षेप में लिखें')}"></textarea><button class="btn" type="submit">${tr('Send help request','मदद का अनुरोध भेजें')}</button></form>${(o.supportRequests||[]).map(r=>`<div class="status-card"><b>${tr('Request saved','अनुरोध सेव हुआ')}</b> · ${esc(r.topic)} · ${esc(translateMessage(r.status,state.profile.language))}<p data-user-content>${esc(r.message)}</p>${(r.replies||[]).map(reply=>`<div class="support-reply"><b>${tr('Staff reply','कर्मचारी का जवाब')} · ${esc(translateMessage(reply.status,state.profile.language))}</b><p data-user-content>${esc(reply.message)}</p><small>${esc(new Date(reply.createdAt).toLocaleString('en-IN',{timeZone:'Asia/Kolkata'}))}</small></div>`).join('')}</div>`).join('')}</section>
  ${button('refresh-order',tr('Refresh order status','ऑर्डर स्थिति फिर देखें'))}${button('new-order',tr('Start another setup','नया सेटअप शुरू करें'),true)}${button('delete-order',tr('Delete this saved order','यह सेव ऑर्डर हटाएँ'),true)}${orderList()}</div>`;
}
function readProfile(){
 if(!$('#profile-form'))return;
 const before=JSON.stringify(state.profile);
 const safeNumber=(id,previous,max)=>{const value=Number($(id).value);return Number.isInteger(value)&&value>=1&&value<=max?value:previous;};
 const selected=[...document.querySelectorAll('[name=need]:checked')].map(input=>input.value).sort();
 const cameraCount=selected.includes('cctv')?safeNumber('#camera-count','',10000):'';
 state.profile={...state.profile,businessName:$('#business').value.trim()||state.profile.businessName,segment:$('#segment').value,
  employees:safeNumber('#employees',state.profile.employees,10000),sites:1,locations:[],
  cityTier:Number($('#tier').value)||state.profile.cityTier,
  budget:safeNumber('#budget',state.profile.budget,10000000),cameraCount,currentTools:$('#tools').value.trim(),needs:selected};
 if(before!==JSON.stringify(state.profile)){state.quote=null;state.reached=0;invalidate();}
}
async function match(){const r=await api('/recommend',{...payload(),consent:state.consent||state.gstConsent});state.quote=r.quote;state.eligible=r.eligibleProducts;state.warnings=r.warnings;}
function items(){return state.quote?.items.map(x=>({productId:x.productId,quantity:x.quantity,...(x.locationId?{locationId:x.locationId}:{})}))||[];}
function editedItems(){return items().map(x=>({...x,quantity:Number(document.getElementById('qty-'+quoteLineKey(x))?.value??x.quantity)}));}
async function reprice(next){state.quote=await api('/quote',{...payload(),consent:state.consent||state.gstConsent,items:next});state.warnings=[];invalidate();}
function on(s,event,handler){const el=$(s);if(el)el.addEventListener(event,handler);}
function wire(){
  on('input[name="need"][value="cctv"]','change',()=>{readProfile();render();});
  on('#addon-location','change',event=>{state.addonLocationId=event.target.value;render();});
  on('#correct-documents','click',()=>run(()=>openOrderCorrections()));
  on('#back-to-order','click',()=>run(()=>openSavedOrder(state.correctionOrderId)));
  on('#package-gst-form','submit',e=>{e.preventDefault();const gstin=$('#package-gstin').value.trim().toUpperCase(),consent=$('#package-gst-consent').checked;if(!consent)return;run(async()=>{const result=await api('/registration-check',{...payload(),profile:{...state.profile,gstin},consent});state.registrationCheck=result.registration;if(result.registration.status==='matched'){state.profile.gstin=gstin;state.gstConsent=true;state.quote=result.recommendation.quote;state.eligible=result.recommendation.eligibleProducts;state.warnings=result.recommendation.warnings;invalidate();}});});
  on('#profile-form','submit',e=>{e.preventDefault();readProfile();run(async()=>{if(state.conversationStorage==='postgresql')await submitSharedForm();else if(state.conversationStorage==='unavailable')throw new Error('PostgreSQL is unavailable. Refresh after the database is restored.');else{await match();move(1);}});});
  wireAdvisor();
  on('#apply-profile','click',()=>{state.profile=state.proposed;state.proposed=null;state.quote=null;state.reached=0;invalidate();render();notify(tr('Suggestions applied. Review your details, then find your package.','सलाह लागू हुई। विवरण जाँचें और पैकेज खोजें।'));});
  on('#back','click',()=>run(()=>navigateJourney(0)));on('#checkout','click',()=>run(async()=>{await reprice(editedItems());if(state.quote.monthly>state.profile.budget)throw new Error('Reduce your package or update your budget first.');move(2);}));on('#update-quantities','click',()=>run(()=>reprice(editedItems())));
  on('#add','click',()=>{
   const p=state.eligible.find(product=>product.id===$('#addon').value);if(!p)return notify('Choose a service first.');
   const location=siteProduct(p)?activeAddonLocation():null;
   let current=items();
   if(location&&['P01','P02','P03','P04','P05','P06'].includes(p.id))current=current.filter(item=>item.locationId!==location.id||!['P01','P02','P03','P04','P05','P06'].includes(item.productId));
   run(()=>reprice([...current,{productId:p.id,quantity:p.unit==='per site'&&!location?state.profile.sites:1,...(location?{locationId:location.id}:{})}]));
  });
  document.querySelectorAll('[data-quantity]').forEach(el=>el.addEventListener('change',()=>{const quantity=Number(el.value);run(()=>reprice(items().map(x=>quoteLineKey(x)===el.dataset.quantity?{...x,quantity}:x)));}));
  document.querySelectorAll('[data-remove]').forEach(el=>el.addEventListener('click',()=>run(()=>reprice(items().filter(x=>quoteLineKey(x)!==el.dataset.remove)))));
  on('#contact-form','submit',e=>{e.preventDefault();state.contact={name:$('#owner').value.trim(),phone:$('#phone').value.trim(),address:$('#address').value.trim()};invalidate();run(async()=>{try{await loadKycCase(false);}catch{}move(3);});});
  on('#consent','change',e=>{const granted=e.target.checked;run(async()=>{if(!granted&&state.kycCaseId)await api('/kyc/cases/'+state.kycCaseId,undefined,'DELETE');state.consent=granted;if(!granted){state.documents={};state.kycCaseId=null;state.aiConsent=false;state.profile.gstin='';state.profile.udyam='';}invalidate();});});
  on('#reader','change',e=>{state.extractionMethod=e.target.value;state.aiConsent=false;invalidate();render();});
  on('#ai-consent','change',e=>{state.aiConsent=e.target.checked;invalidate();render();});
  for(const id of ['gstin','udyam'])on('#'+id,'input',e=>{state.profile[id]=e.target.value.trim().toUpperCase();invalidate();const old=$('.verification-results');if(old)old.remove();});
  document.querySelectorAll('[data-doc]').forEach(el=>el.addEventListener('change',()=>{const file=el.files[0];if(!file)return;const isPdf=file.type==='application/pdf'||file.name.toLowerCase().endsWith('.pdf'),isImage=['image/png','image/jpeg'].includes(file.type);if((!isImage&&!isPdf)||file.size>2*1024*1024){notify('Choose a JPEG, PNG, or PDF document up to 2 MB.');el.value='';return;}run(async()=>{const dataUrl=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(new Error('Could not read document.'));reader.readAsDataURL(file);});state.documents[el.dataset.doc]={name:file.name,dataUrl};invalidateDocument(el.dataset.doc);});}));
  on('#verify','click',()=>run(async()=>{if(!state.consent)throw new Error('Please grant verification consent first.');state.verification=await api('/verify',{...payload(),caseId:state.kycCaseId,consentVersion:'2026-10-smart-kyc-v3',items:items(),extractionMethod:state.extractionMethod,aiConsent:state.aiConsent,contact:state.contact,documents:Object.entries(state.documents).map(([kind,doc])=>({kind,name:doc.name,...(doc.documentId?{documentId:doc.documentId}:{dataUrl:doc.dataUrl})}))});state.kycCaseId=state.verification.caseId||null;for(const d of state.verification.documents)if(d.documentId)state.documents[d.kind]={name:d.filename||docNames[d.kind],documentId:d.documentId};state.fieldsReviewed=false;state.eligible=(await api('/recommend',{...payload(),consent:state.consent||state.gstConsent})).eligibleProducts;},tr('Reading documents and checking the sample registries…','दस्तावेज़ पढ़े जा रहे हैं और नमूना रिकॉर्ड जाँचे जा रहे हैं…')));
  on('#request-kyc-review','click',()=>run(async()=>{const result=await api('/kyc/cases/'+state.kycCaseId+'/review-request',{consent:state.consent});state.verification={...state.verification,reviewRequest:result.result.reviewRequest};notify(tr('Review requested locally. No external reviewer was notified.','स्थानीय समीक्षा अनुरोध सेव हुआ। किसी बाहरी समीक्षक को सूचना नहीं भेजी गई।'));}));
  document.querySelectorAll('[data-replace-doc]').forEach(el=>el.onclick=()=>document.querySelector('[data-doc="'+el.dataset.replaceDoc+'"]').click());
  on('#refresh-kyc','click',()=>run(()=>loadKycCase(false)));
  on('#delete-kyc','click',()=>run(async()=>{await api('/kyc/cases/'+state.kycCaseId,undefined,'DELETE');state.kycCaseId=null;state.documents={};invalidate();}));
  document.querySelectorAll('[data-preview]').forEach(el=>el.onclick=()=>previewDocument(el.dataset.preview));
  document.querySelectorAll('[data-preview-saved]').forEach(el=>el.onclick=()=>previewDocument(null,el.dataset.previewSaved));
  on('#fields-reviewed','change',e=>{state.fieldsReviewed=e.target.checked;});
  on('#review-services','click',()=>run(()=>navigateJourney(1)));
  document.querySelectorAll('[data-clear-doc]').forEach(el=>el.addEventListener('click',()=>{delete state.documents[el.dataset.clearDoc];invalidateDocument(el.dataset.clearDoc);render();}));
  on('#place-order','click',()=>run(async()=>{if((state.verification.documents||[]).some(d=>d.reviewFields&&Object.keys(d.reviewFields).length)&&!state.fieldsReviewed)throw new Error('Review the extracted document fields before continuing.');if(state.correctionOrderId){state.order=await api('/orders/'+state.correctionOrderId+'/verification',{verificationId:state.verification.id,fieldsReviewed:state.fieldsReviewed});state.correctionOrderId=null;state.documents={};move(4);return;}state.order=await api('/orders',{...payload(),contact:state.contact,items:items(),fieldsReviewed:state.fieldsReviewed,verificationId:state.verification.id,requestKey:state.requestKey});state.documents={};state.orders=(await api('/orders')).orders;move(4);}));
  on('#support-form','submit',e=>{e.preventDefault();const topic=$('#support-topic').value,message=$('#support-message').value.trim();run(async()=>{await api('/orders/'+state.order.id+'/support',{topic,message});state.order=await api('/orders/'+state.order.id);notify('Help request saved in this demo. No support team was notified.');});});
  on('#refresh-order','click',()=>run(async()=>{state.order=await api('/orders/'+state.order.id);}));
  on('#new-order','click',()=>{state.activeConversation=null;state.pendingForm=null;state.requirementsRevision=0;sessionStorage.removeItem('udyam_active_chat');const url=new URL(location.href);url.searchParams.delete('session_id');history.replaceState(null,'',url);state.order=null;state.correctionOrderId=null;state.proposed=null;state.extractionMethod='local';state.documents={};state.kycCaseId=null;state.profile.gstin='';state.profile.udyam='';state.gstConsent=false;state.registrationCheck=null;state.consent=false;state.aiConsent=false;state.reached=0;state.quote=null;state.messages=[];invalidate();move(0);});
  on('#delete-order','click',()=>run(async()=>{await api('/orders/'+state.order.id,null,'DELETE');state.orders=(await api('/orders')).orders;state.order=state.orders.length?await api('/orders/'+state.orders[0].id):null;state.quote=state.order?.quote||null;if(state.order)state.profile={...state.order.profile,language:preferredLanguage(),gstin:'',udyam:''};}));
  wireSavedOrders($('#view'));
}
document.querySelectorAll('.step').forEach(el=>el.addEventListener('click',()=>{if(state.busy)return;const step=Number(el.dataset.step);if(state.order&&step!==4&&!(state.correctionOrderId&&step===3))return notify('Start another setup to create a new order.');if(state.step===2&&$('#owner'))state.contact={name:$('#owner').value,phone:$('#phone').value,address:$('#address').value};if(step<=state.reached)run(()=>navigateJourney(step));}));
$('#language').addEventListener('change',e=>{if(state.busy)return;if(state.step===2&&$('#owner'))state.contact={name:$('#owner').value,phone:$('#phone').value,address:$('#address').value};if(state.step===0&&$('#profile-form'))readProfile();state.profile.language=e.target.value;try{localStorage.setItem('udyam_language',e.target.value);}catch{}invalidate();render();});
$('#close-document-preview').addEventListener('click',()=>{$('#document-preview').close();$('#document-preview-image').removeAttribute('src');});
$('#privacy').addEventListener('click',()=>$('#privacy-dialog').showModal());$('#close-privacy').addEventListener('click',()=>$('#privacy-dialog').close());
document.body.addEventListener('invalid',e=>{if(e.target.closest('.cl-rootBox,.cl-modalBackdrop'))return;if(state.profile.language==='hi'&&e.target.setCustomValidity)e.target.setCustomValidity(e.target.validity.valueMissing?'कृपया यह जानकारी भरें।':'कृपया दी गई सीमा में सही जानकारी भरें।');},true);
document.body.addEventListener('input',e=>{if(e.target.closest('.cl-rootBox,.cl-modalBackdrop'))return;if(e.target.setCustomValidity)e.target.setCustomValidity('');});
on('#my-orders','click',()=>run(()=>showSavedOrders()));
on('#notification-toggle','click',event=>{state.notificationsOpen=!state.notificationsOpen;$('#notification-panel').hidden=!state.notificationsOpen;event.currentTarget.setAttribute('aria-expanded',String(state.notificationsOpen));});
on('#mark-notifications-read','click',()=>markNotificationsRead(state.notifications.filter(item=>!item.read).map(item=>item.id)).catch(()=>notify('Could not update notification status. Please try again.')));
document.body.addEventListener('click',event=>{const link=event.target.closest('[data-notification-link]');if(link){event.preventDefault();const href=link.href;markNotificationsRead([link.dataset.notificationId]).catch(()=>{}).finally(()=>location.assign(href));return;}if(state.notificationsOpen&&!event.target.closest('#notification-center')){state.notificationsOpen=false;$('#notification-panel').hidden=true;$('#notification-toggle').setAttribute('aria-expanded','false');}});
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&state.notificationsOpen){state.notificationsOpen=false;$('#notification-panel').hidden=true;$('#notification-toggle').setAttribute('aria-expanded','false');$('#notification-toggle').focus();}});
on('#close-orders','click',()=>$('#orders-dialog').close());
async function init(){try{const session=await api('/session');state.customerSignedIn=!!session.auth?.signedIn;if(!state.customerSignedIn)throw new Error('Sign in to access your business setup and place orders.');$('#auth-gate').hidden=true;$('#customer-app').hidden=false;$('#my-orders').hidden=false;state.mode=session.mode;state.provider=session.provider;state.externalImageReading=session.externalImageReading;state.kycStorage=session.kycStorage||'temporary';state.conversationStorage=session.conversationStorage||'disabled';if(state.conversationStorage==='postgresql'){try{state.conversations=(await api('/sessions')).sessions;const saved=new URL(location.href).searchParams.get('session_id')||sessionStorage.getItem('udyam_active_chat');if(saved&&state.conversations.some(c=>c.id===saved))await loadConversation(saved);}catch{state.conversationStorage='unavailable';notify('Saved conversations are unavailable. Check PostgreSQL and refresh; the package form remains available.');}}if(state.conversationStorage!=='postgresql'&&session.advisorProfile)state.profile={...state.profile,...session.advisorProfile,language:preferredLanguage()};state.orders=(await api('/orders')).orders;const params=new URL(location.href).searchParams;const restore=orderToRestore(state.orders,{orderId:params.get('order_id'),journeyId:state.activeConversation,view:params.get('view')});if(restore){await openSavedOrder(restore);if(params.get('view')==='verify'&&state.order.verification.caseId)await openOrderCorrections();return;}if(state.activeConversation&&new URL(location.href).searchParams.get('view')==='verify'){try{await loadKycCase(true);if(state.kycCaseId){state.step=3;state.reached=3;}}catch{}}if(state.activeConversation&&state.quote&&new URL(location.href).searchParams.get('view')==='package'){state.step=1;state.reached=Math.max(1,state.reached);}render();}catch(e){$('#view').innerHTML='<div class="card"><h2>Could not connect</h2><p>Run npm start and open http://localhost:3000. Refresh to retry.</p></div>';notify(e.message);}}
if(await initializeAccount())init().then(()=>{if(state.customerSignedIn)startNotifications();});

let pollingOrder=false;
async function pollOrder(){
  if(document.hidden||state.step!==4||!state.order||state.busy||pollingOrder)return;
  const id=state.order.id;
  pollingOrder=true;
  try{
    const latest=await api('/orders/'+id);
    if(state.step!==4||state.order?.id!==id||state.busy)return;
    if(JSON.stringify(latest)!==JSON.stringify(state.order)){
      const draft=$('#support-message')?.value,topic=$('#support-topic')?.value;
      state.order=latest;render();
      if(draft&&$('#support-message'))$('#support-message').value=draft;
      if(topic&&$('#support-topic'))$('#support-topic').value=topic;
    }
    if($('#poll-status'))$('#poll-status').textContent='Last checked '+new Date().toLocaleTimeString();
  }catch{if($('#poll-status'))$('#poll-status').textContent='Connection unavailable. Retrying automatically.';}
  finally{pollingOrder=false;}
}
setInterval(pollOrder,10000);
document.addEventListener('visibilitychange',()=>{pollOrder();refreshNotifications();});
